/**
 * Frame-sequence preloader (singleton) for the scroll-scrubbed background.
 *
 * The same 120 frames exist in two sets:
 *   /frames/frame-000.webp    1600×844, landscape: desktop and tablets
 *   /frames-m/frame-000.webp  480×800, centre crop: phones held upright
 * The canvas draws each frame "cover", so an upright phone only ever shows the
 * central strip of the landscape frame. The portrait set is that strip: it
 * looks the same there for about a quarter of the bytes.
 * Both are generated by scripts/optimize-frames.cjs.
 *
 * The folders are cached for a month (public/_headers) and the file names are
 * not hashed: if the footage ever changes, rename the folders.
 *
 * Nothing here blocks the first paint. The backdrop only shows after scrolling
 * past the hero, so preloading starts once the hero images are in, at low
 * priority, and coarse-to-fine: a usable sequence exists after a few frames.
 */

export const FRAME_COUNT = 120;

export interface FramesState {
  images: (HTMLImageElement | null)[];
  loaded: number;
}

export const framesState: FramesState = {
  images: Array.from({ length: FRAME_COUNT }, () => null),
  loaded: 0,
};

let started = false;
const progressListeners = new Set<(progress: number) => void>();

export const onFramesProgress = (fn: (progress: number) => void) => {
  progressListeners.add(fn);
  fn(framesState.loaded / FRAME_COUNT);
  return () => progressListeners.delete(fn);
};

/** Fetch order: both ends, then every 24th frame, 12th, 6th, 3rd, and the rest. */
export const frameOrder = (): number[] => {
  const order: number[] = [];
  const seen = new Set<number>();
  const push = (i: number) => {
    if (i < FRAME_COUNT && !seen.has(i)) {
      seen.add(i);
      order.push(i);
    }
  };
  push(0);
  push(FRAME_COUNT - 1);
  for (const step of [24, 12, 6, 3, 1]) {
    for (let i = 0; i < FRAME_COUNT; i += step) push(i);
  }
  return order;
};

/** What a data-saver or slow connection gets: every 6th frame plus the last. */
const LITE_FRAMES = 21;
const CONCURRENCY = 4;

type Connection = { saveData?: boolean; effectiveType?: string };

/** Kick off (idempotent) preloading of the frame sequence. */
export const preloadFrames = () => {
  if (started || typeof window === 'undefined') return;
  started = true;

  const uprightPhone = window.innerWidth < 768 && window.innerHeight > window.innerWidth;
  const dir = uprightPhone ? '/frames-m' : '/frames';
  const frameSrc = (i: number) => `${dir}/frame-${String(i).padStart(3, '0')}.webp`;

  const connection = (navigator as Navigator & { connection?: Connection }).connection;
  const lite = !!connection && (connection.saveData === true || /2g|3g/.test(connection.effectiveType ?? ''));
  const queue = lite ? frameOrder().slice(0, LITE_FRAMES) : frameOrder();
  let cursor = 0;

  const notify = () => {
    const p = framesState.loaded / FRAME_COUNT;
    progressListeners.forEach((fn) => fn(p));
  };

  const next = () => {
    if (cursor >= queue.length) return;
    const index = queue[cursor++];
    const img = new Image();
    img.decoding = 'async';
    // Content images always win the connection over the backdrop.
    (img as HTMLImageElement & { fetchPriority?: string }).fetchPriority = 'low';
    img.onload = () => {
      framesState.images[index] = img;
      framesState.loaded++;
      notify();
      next();
    };
    img.onerror = () => {
      framesState.loaded++;
      notify();
      next();
    };
    img.src = frameSrc(index);
  };

  for (let i = 0; i < CONCURRENCY; i++) next();
};

/** Nearest loaded frame to the requested index (falls back outward). */
export const nearestLoadedFrame = (index: number): HTMLImageElement | null => {
  const i = Math.max(0, Math.min(FRAME_COUNT - 1, Math.round(index)));
  if (framesState.images[i]) return framesState.images[i];
  for (let d = 1; d < FRAME_COUNT; d++) {
    if (framesState.images[i - d]) return framesState.images[i - d];
    if (framesState.images[i + d]) return framesState.images[i + d];
  }
  return null;
};
